      dhead = 301,
      dialog = 1,
      music = "24_Romantic_Quiet",
      renming = "$u",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      sentence = "I guess I can be like that because someone always accepts me for who I am.",
